public class Solution {
    public static void main(String[] args) {
        if (args.length != 3) {
            args = new String[]{"100", "/", "4"};
        }
        try {
            double op1 = Double.parseDouble(args[0]);
            String operator = args[1];
            double op2 = Double.parseDouble(args[2]);

            double result;
            switch (operator) {
                case "+": result = op1 + op2; break;
                case "-": result = op1 - op2; break;
                case "*": result = op1 * op2; break;
                case "/":
                    if (op2 == 0) {
                        System.out.println("Error: Division by zero");
                        return;
                    }
                    result = op1 / op2;
                    break;
                default:
                    System.out.println("Error: Invalid operator '" + operator + "'");
                    return;
            }
            System.out.printf("Calculation: %.1f %s %.1f = %.1f%n", op1, operator, op2, result);
        } catch (NumberFormatException e) {
            System.out.println("Error: Operands must be valid numbers.");
        }
    }
}

