import java.util.Arrays;

public class Solution {
    public static void main(String[] args) {
        if (args.length == 0) {
            args = new String[]{"5", "2", "8", "1", "3"};
        }
        int[] asc = new int[args.length];
        for (int i = 0; i < args.length; i++) {
            asc[i] = Integer.parseInt(args[i]);
        }
        int[] desc = asc.clone();

        // Bubble sort ascending
        for (int i = 0; i < asc.length - 1; i++) {
            for (int j = 0; j < asc.length - 1 - i; j++) {
                if (asc[j] > asc[j + 1]) {
                    int tmp = asc[j];
                    asc[j] = asc[j + 1];
                    asc[j + 1] = tmp;
                }
            }
        }

        // Bubble sort descending
        for (int i = 0; i < desc.length - 1; i++) {
            for (int j = 0; j < desc.length - 1 - i; j++) {
                if (desc[j] < desc[j + 1]) {
                    int tmp = desc[j];
                    desc[j] = desc[j + 1];
                    desc[j + 1] = tmp;
                }
            }
        }

        System.out.println("Ascending: " + Arrays.toString(asc));
        System.out.println("Descending: " + Arrays.toString(desc));
    }
}

