import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class Solution {
    public static void main(String[] args) {
        // Demonstration cipher created from 'SecretPayload' XORed with 'myKey'
        if (args.length < 2) {
            args = new String[]{"Aw4eEwESDRgcBxcCBA==", "myKey"};
        }
        String base64Token = args[0];
        String key = args[1];

        byte[] cipherBytes = Base64.getDecoder().decode(base64Token);
        byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        byte[] decrypted = new byte[cipherBytes.length];

        for (int i = 0; i < cipherBytes.length; i++) {
            decrypted[i] = (byte) (cipherBytes[i] ^ keyBytes[i % keyBytes.length]);
        }

        String recoveredMessage = new String(decrypted, StandardCharsets.UTF_8);
        System.out.println("Decrypted payload: " + recoveredMessage);
    }
}
